<script setup lang="ts">
import { computed, nextTick, onMounted, ref, shallowRef, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ArrowLeft, BookOpen, Copy, Download, Search } from '@lucide/vue'
import OpenDocsCode from '../components/OpenDocsCode.vue'
import OpenDocsSchema from '../components/OpenDocsSchema.vue'
import { copyDocumentation, dereference, documentAsset, requestExample, schemaConstraints, schemaExample, schemaType, type Endpoint, type GuideSection, type PublicConfig, type Spec } from '../services/open-platform-docs'

const route=useRoute(), router=useRouter()
const spec=shallowRef<Spec>(), sections=shallowRef<GuideSection[]>([]), config=shallowRef<PublicConfig>()
const query=ref(''), modelQuery=ref(''), loading=ref(true), error=ref(''), configError=ref(false), copyMessage=ref('')
const downloads=[{name:'openapi.yaml',label:'OpenAPI YAML'},{name:'openapi.json',label:'OpenAPI JSON'},{name:'signing-v1.md',label:'签名规范'},{name:'signing-vectors.json',label:'签名测试向量'},{name:'OwlClient.go',label:'Go 示例'},{name:'owl_client.py',label:'Python 示例'},{name:'OwlClient.java',label:'Java 示例'},{name:'guide.json',label:'开发指南数据'}]
const origin=computed(()=>config.value?.public_url||window.location.origin)
const audience=computed(()=>config.value?.audience||'<请向管理员确认 Audience>')
const endpoints=computed<Endpoint[]>(()=>spec.value?Object.entries(spec.value.paths).flatMap(([path,methods])=>Object.entries(methods).map(([method,operation])=>({...operation,path,method:method.toUpperCase()}))):[])
const filtered=computed(()=>{const text=query.value.trim().toLowerCase();return endpoints.value.filter(v=>`${v.method} ${v.path} ${v.summary} ${v.description} ${v['x-scope']}`.toLowerCase().includes(text))})
const groups=computed(()=>['业务','媒体','管理','公共'].map(name=>({name,items:filtered.value.filter(v=>v.tags.includes(name))})).filter(v=>v.items.length))
const current=computed(()=>endpoints.value.find(v=>v.operationId===route.query.operation))
const page=computed(()=>route.query.operation?'api':String(route.query.page||'start'))
const section=computed(()=>sections.value.find(v=>v.id===page.value)||sections.value[0])
const parameters=computed(()=>current.value&&spec.value?(current.value.parameters||[]).map(v=>dereference(spec.value!,v)):[])
const requestSchema=computed(()=>current.value?.requestBody?.content['application/json']?.schema)
const responses=computed(()=>current.value&&spec.value?Object.entries(current.value.responses).map(([status,value])=>({status,...dereference(spec.value!,value)})):[])
const success=computed(()=>responses.value.find(v=>v.status==='200'))
const responseSchema=computed(()=>success.value?.content?.['application/json']?.schema)
const models=computed(()=>spec.value?Object.entries(spec.value.components.schemas).filter(([name,schema])=>`${name} ${schema.description||''}`.toLowerCase().includes(modelQuery.value.toLowerCase())):[])
function text(value:string){return value.split('<当前部署开放地址>').join(origin.value).split('<当前部署 Audience>').join(audience.value).split('http://10.144.0.20:15123').join(origin.value)}
function json(value:unknown){return text(JSON.stringify(value,null,2))}
const bodyExample=computed(()=>spec.value&&current.value?requestExample(spec.value,current.value):undefined)
const responseExample=computed(()=>spec.value&&responseSchema.value?json(success.value?.content?.['application/json']?.example??schemaExample(spec.value,responseSchema.value)):'')
const httpExample=computed(()=>{
 const e=current.value;if(!e)return ''
 const ids:Record<string,string>={app:'app-001',id:e.path.includes('/recordings/')||e.path.includes('/events/')?'101':'channel-001',session:'session-001',task:'task-001',command:'command-001',subscription:'subscription-001',delivery:'delivery-001',credential:'credential-001',target:'target-001',kind:'recording',path:'content'}
 let path=e.path.replace(/\{([^}]+)\}/g,(_match,key:string)=>ids[key]||'resource-001')
 const lines:string[]=[]
 if(e.tags.includes('媒体'))path+='?ticket=<票据接口返回的随机票据>'
 else if(parameters.value.some(v=>v.in==='query'&&v.name==='size'))path+='?'+(parameters.value.some(v=>v.name==='page')?'page=1&':'')+'size=50'
 lines.push(`${e.method} ${origin.value}${path}`)
 if(e.tags.includes('业务'))lines.push('Authorization: OWL-HMAC-SHA256 Credential=<AK>,Signature=<计算得到的小写hex>',`X-Owl-Audience: ${audience.value}`,'X-Owl-Timestamp: <当前UTC Unix秒>','X-Owl-Nonce: <本次随机Base64URL>','X-Owl-Content-SHA256: <实际body的SHA256小写hex>')
 if(e.tags.includes('管理'))lines.push('Authorization: Bearer <管理员JWT>')
 if(parameters.value.some(v=>v.name==='Idempotency-Key'))lines.push('Idempotency-Key: <本次业务幂等键>')
 if(bodyExample.value!==undefined)lines.push('Content-Type: application/json','',JSON.stringify(bodyExample.value,null,2))
 return lines.join('\n')
})
async function copyLink(){try{await copyDocumentation(window.location.href);copyMessage.value='文档链接已复制'}catch{copyMessage.value='请复制浏览器地址栏'}}
async function load(){
 loading.value=true;error.value=''
 try {
  const results=await Promise.all(['openapi.json','guide.json'].map(async name=>{const res=await fetch(documentAsset(name),{cache:'no-cache'});if(!res.ok)throw new Error('文档资源加载失败，请刷新重试');return res.json()}))
  spec.value=results[0] as Spec;sections.value=(results[1] as {sections:GuideSection[]}).sections
 }catch(cause){error.value=cause instanceof Error?cause.message:'文档加载失败'}finally{loading.value=false}
 try {
  const base=(import.meta.env.VITE_API_BASE_URL||'/').replace(/\/$/,'')
  const res=await fetch(`${base}/open-platform/docs/config`,{cache:'no-store'})
  if(!res.ok)throw new Error('配置不可用')
  config.value=(await res.json()).data as PublicConfig;configError.value=false
 }catch{configError.value=true}
}
watch(()=>route.fullPath,async()=>{copyMessage.value='';await nextTick();window.scrollTo({top:0,behavior:'instant'})})
onMounted(load)
</script>

<template>
 <div class="developer-docs">
  <header class="docs-header"><RouterLink :to="{name:'open-platform-docs'}" class="docs-brand"><span class="brand-icon"><BookOpen :size="22"/></span><span>三方应用开放平台<small>开发者文档 · API {{ spec?.info.version || 'v1' }}</small></span></RouterLink><div class="header-actions"><button class="doc-btn" @click="copyLink"><Copy :size="15"/>{{ copyMessage || '复制分享链接' }}</button><RouterLink class="page-back-btn" :to="{name:'open-platform'}" aria-label="返回管理平台" title="返回管理平台"><ArrowLeft aria-hidden="true"/></RouterLink></div></header>
  <div v-if="loading" class="docs-loading" role="status">正在加载完整接口文档…</div>
  <div v-else-if="error" class="docs-loading" role="alert">{{ error }} <button class="doc-btn" @click="load">重新加载</button></div>
  <div v-else-if="spec" class="docs-layout">
   <aside class="docs-nav" aria-label="开发文档目录">
    <label class="docs-search"><Search :size="16"/><input v-model="query" placeholder="搜索接口、路径或 Scope" aria-label="搜索接口" type="search"/></label>
    <nav class="guide-nav"><RouterLink v-for="item in sections" :key="item.id" :class="{active:page===item.id}" :to="{name:'open-platform-docs',query:{page:item.id}}">{{ item.title }}</RouterLink><RouterLink :class="{active:page==='models'}" :to="{name:'open-platform-docs',query:{page:'models'}}">完整字段字典</RouterLink></nav>
    <p class="nav-heading">接口参考 <span>{{ filtered.length }} / {{ endpoints.length }}</span></p>
    <p v-if="!filtered.length" class="no-results">没有匹配的接口，试试路径或权限名称。</p>
    <details v-for="group in groups" :key="group.name" class="api-group" :open="group.name==='业务'||Boolean(query)||current?.tags.includes(group.name)"><summary>{{ group.name==='管理'?'管理接口（管理员）':group.name+'接口' }} <span>{{ group.items.length }}</span></summary><RouterLink v-for="endpoint in group.items" :key="endpoint.operationId" class="api-nav" :class="{active:current?.operationId===endpoint.operationId}" :to="{name:'open-platform-docs',query:{operation:endpoint.operationId}}"><span class="http-method" :data-method="endpoint.method">{{ endpoint.method }}</span><span>{{ endpoint.summary }}</span></RouterLink></details>
   </aside>
   <main class="docs-main" id="docs-main">
    <div class="environment"><div><small>开放地址</small><code>{{ origin }}</code></div><div><small>签名 Audience</small><code>{{ audience }}</code></div><span class="transport">{{ config?.allow_http?'HTTP 已启用':'HTTPS' }}</span></div>
    <p v-if="configError" class="docs-notice" role="status">暂时无法读取部署配置，当前展示本站地址；调用前请向管理员确认开放地址和 Audience。</p><p v-else-if="config&&!config.enabled" class="docs-notice">文档可阅读，当前开放服务尚未就绪，请联系管理员。</p>
    <template v-if="page==='api'&&current">
     <p class="docs-eyebrow">{{ current.tags.join(' / ') }}接口</p><h1>{{ current.summary }}</h1><div class="endpoint-path"><span class="http-method" :data-method="current.method">{{ current.method }}</span><code>{{ current.path }}</code></div><p class="intro">{{ current.description }}</p><div class="scope-line"><strong>所需权限</strong><code>{{ current['x-scope'] }}</code></div>
     <h2>请求参数</h2><div v-if="parameters.length" class="docs-table"><table><thead><tr><th>参数</th><th>位置</th><th>类型 / 必填</th><th>说明</th></tr></thead><tbody><tr v-for="parameter in parameters" :key="`${parameter.in}-${parameter.name}`"><td><code>{{ parameter.name }}</code></td><td>{{ {path:'路径',query:'Query',header:'请求头'}[parameter.in] || parameter.in }}</td><td>{{ schemaType(parameter.schema) }}<small>{{ parameter.required?'必填':'可选' }}</small></td><td>{{ parameter.description }}<small v-if="schemaConstraints(parameter.schema)">{{ schemaConstraints(parameter.schema) }}</small></td></tr></tbody></table></div><p v-else>无路径、查询或请求头参数。</p>
     <template v-if="requestSchema"><h2>JSON 请求体</h2><p>{{ current.requestBody?.description }}</p><OpenDocsSchema :spec="spec" :schema="requestSchema"/><OpenDocsCode :code="json(bodyExample)" language="json"/></template><p v-else class="docs-note">{{ current.method==='GET'||current.method==='DELETE'?'不发送请求体。业务签名中的 Content-Type 为空字符串。':'无需额外请求体。' }}</p>
     <h2>完整请求示例</h2><p class="docs-note">下面的 ID、时间、nonce 和签名为占位内容，请使用下载的客户端生成实际签名。创建或控制操作不会在此页面执行。</p><OpenDocsCode :code="httpExample" language="http"/>
     <h2>响应字段与结果</h2><template v-if="responseSchema"><p>业务响应包装为 code、message、request_id、data；失败时 data=null。</p><OpenDocsSchema :spec="spec" :schema="responseSchema" response/><OpenDocsCode :code="responseExample" language="json"/></template><template v-else><p>{{ success?.description }}。成功为媒体字节，Content-Type 随资源变化：HLS 为 application/vnd.apple.mpegurl，FLV、MP4 或图片按对应媒体类型返回。票据接口返回的 URL 应原样使用。</p><OpenDocsCode code="GET /openmedia/v1/recording/101/content?ticket=<短期票据>&#10;Range: bytes=0-1023&#10;&#10;HTTP/1.1 206 Partial Content&#10;Content-Range: bytes 0-1023/1048576&#10;&#10;<媒体字节>" language="http"/></template>
     <h2>HTTP 状态</h2><div class="docs-table"><table><thead><tr><th>状态</th><th>说明</th></tr></thead><tbody><tr v-for="response in responses" :key="response.status"><td><code>{{ response.status }}</code></td><td>{{ response.description }}</td></tr></tbody></table></div><p>失败 code 与处理建议见 <RouterLink :to="{name:'open-platform-docs',query:{page:'errors'}}">返回约定与错误码</RouterLink>。</p>
    </template>
    <template v-else-if="page==='api'"><h1>未找到接口</h1><p>该文档链接对应的接口不存在，请从左侧目录重新选择。</p></template>
    <template v-else-if="page==='models'"><p class="docs-eyebrow">SCHEMA REFERENCE</p><h1>完整字段字典</h1><p class="intro">覆盖请求体、响应对象和回调事件。点击模型展开全部字段；每个接口页也列出对应的嵌套字段。</p><input v-model="modelQuery" class="model-search" type="search" placeholder="搜索模型名称，如 CallbackEvent、PTZInput" aria-label="搜索字段模型"/><details v-for="[name,schema] in models" :key="name" class="model-card"><summary><code>{{ name }}</code><span>{{ Object.keys(schema.properties||{}).length }} 个字段</span></summary><p v-if="schema.description">{{ schema.description }}</p><OpenDocsSchema :spec="spec" :schema="schema" :response="!name.endsWith('Input')&&!name.endsWith('Patch')"/></details></template>
    <template v-else-if="section"><p class="docs-eyebrow">DEVELOPER GUIDE</p><h1>{{ section.title }}</h1><p class="intro">{{ section.intro }}</p><div v-if="section.id==='downloads'" class="download-grid"><a v-for="file in downloads" :key="file.name" :href="documentAsset(file.name)" :download="file.name"><Download :size="18"/><strong>{{ file.label }}</strong><small>{{ file.name }}</small></a></div><section v-for="(block,index) in section.blocks" :key="index" class="guide-section"><h2>{{ block.title }}</h2><p v-for="(paragraph,i) in block.paragraphs" :key="i">{{ text(paragraph) }}</p><ol v-if="block.steps"><li v-for="(step,i) in block.steps" :key="i">{{ text(step) }}</li></ol><div v-if="block.columns&&block.rows" class="docs-table"><table><thead><tr><th v-for="column in block.columns" :key="column">{{ column }}</th></tr></thead><tbody><tr v-for="(row,i) in block.rows" :key="i"><td v-for="(cell,j) in row" :key="j">{{ text(cell) }}</td></tr></tbody></table></div><OpenDocsCode v-if="block.code" :code="text(block.code)" :language="block.language"/></section></template>
    <footer class="docs-footer"><span>文档与当前版本一同部署 · {{ endpoints.length }} 个接口操作 · {{ Object.keys(spec.components.schemas).length }} 个字段模型</span><button @click="router.push({name:'open-platform-docs',query:{page:'downloads'}})">下载接口契约与示例</button></footer>
   </main>
  </div>
 </div>
</template>

<style scoped>
.developer-docs{min-height:100vh;background:#fff;color:var(--ink);font-size:14px;line-height:1.8}.docs-header{position:sticky;top:0;z-index:20;height:56px;background:#fff;border-bottom:1px solid #dce2ea;display:flex;align-items:center;justify-content:space-between;padding:0 28px;gap:20px}.docs-brand{display:flex;align-items:center;gap:12px;color:#142b4a;font-size:17px;font-weight:700;text-decoration:none;line-height:1.5}.brand-icon{display:grid;place-items:center;background:#184d89;color:white;width:32px;height:32px;border-radius:6px}.docs-brand small{display:block;font-size:12px;color:#5f6e81;font-weight:400}.header-actions{display:flex;gap:10px}.doc-btn{display:inline-flex;align-items:center;gap:7px;padding:7px 11px;border:1px solid #d4dce7;border-radius:7px;background:white;color:#28496e;white-space:nowrap;font-size:12px;text-decoration:none}.doc-btn:hover{background:#f2f6fb}.docs-layout{max-width:1560px;margin:0 auto;display:grid;grid-template-columns:240px minmax(0,1fr)}.docs-nav{position:sticky;top:56px;height:calc(100dvh - 56px);overflow:auto;padding:22px 16px 40px;border-right:1px solid #e1e7ef;background:#fbfcfe}.docs-search{display:flex;align-items:center;gap:8px;border:1px solid #ccd6e3;background:#fff;border-radius:7px;padding:7px 9px;color:#64748b}.docs-search input{width:100%;min-width:0;background:none;border:0;outline:0;font-size:12px}.docs-search:focus-within{outline:2px solid #4b89d1}.guide-nav{display:grid;gap:3px;padding:18px 0}.guide-nav a{padding:6px 10px;color:#354a64;border-radius:5px;font-size:13px;text-decoration:none}.guide-nav a:hover,.api-nav:hover{background:#eef3f9}.guide-nav a.active,.api-nav.active{background:var(--blue-soft);color:var(--blue);font-weight:600}.nav-heading{display:flex;justify-content:space-between;border-top:1px solid #e2e8f0;padding:16px 4px 6px;color:#607087;font-size:12px;font-weight:600}.nav-heading span{font-weight:400}.api-group{margin-top:8px}.api-group summary{cursor:pointer;color:#405570;padding:6px 4px;font-size:12px;font-weight:700}.api-group summary span{float:right;color:#6a7a8f;margin-right:4px}.api-nav{display:flex;align-items:flex-start;gap:7px;padding:7px 5px;border-radius:5px;text-decoration:none;color:#354a64;font-size:12px;line-height:1.6}.http-method{display:inline-block;flex-shrink:0;min-width:47px;font:700 10px/1.9 ui-monospace,monospace;color:#1a745b;background:#e6f4ee;border-radius:4px;text-align:center;padding:1px 4px}.http-method[data-method=POST]{color:#225b9c;background:#e6effb}.http-method[data-method=PATCH],.http-method[data-method=PUT]{color:#936314;background:#fcf1d8}.http-method[data-method=DELETE]{color:#a52b48;background:#fce9ee}.docs-main{min-width:0;padding:24px 28px 40px;max-width:1180px}.environment{display:flex;flex-wrap:wrap;gap:12px 32px;align-items:center;background:#f5f8fc;border:1px solid #dde5ef;border-radius:9px;padding:14px 18px;margin-bottom:34px}.environment small{display:block;color:#65768d;font-size:11px}.environment code{font-size:12px;overflow-wrap:anywhere}.transport{margin-left:auto;color:#51657c;font-size:11px;border:1px solid #cfdae7;border-radius:4px;padding:2px 8px}.docs-eyebrow{color:#60758d;font:600 11px/1.8 ui-monospace,monospace;letter-spacing:.08em;margin-bottom:6px}.docs-main h1{font-size:24px;line-height:1.4;font-weight:700;color:var(--ink-strong);margin:0 0 18px}.docs-main h2{font-size:18px;font-weight:700;margin:30px 0 12px;color:#1d3655}.docs-main p{margin:12px 0;overflow-wrap:anywhere}.docs-main p.intro{font-size:15px;color:#53647b;margin-bottom:24px;line-height:1.9}.endpoint-path{display:flex;align-items:center;gap:12px;background:var(--bg);padding:13px 16px;border:1px solid #dce2ea;border-radius:8px;margin-bottom:18px;overflow:auto}.endpoint-path code{white-space:nowrap;font-size:13px}.scope-line{display:flex;align-items:baseline;gap:16px;flex-wrap:wrap;padding:11px 0;border-block:1px solid #e6ebf1;font-size:13px}.scope-line code{color:#245389}.docs-table{overflow:auto;border:1px solid #dce2ea;border-radius:8px;margin:14px 0}.docs-table table{border-collapse:collapse;width:100%;font-size:13px;min-width:570px}.docs-table th,.docs-table td{padding:11px 14px;border-bottom:1px solid #e7ebf1;vertical-align:top;text-align:left;overflow-wrap:anywhere}.docs-table th{background:var(--bg);font-weight:600;color:#46556d}.docs-table tr:last-child td{border-bottom:0}.docs-table small{display:block;color:#5d6e84;font-size:12px;margin-top:4px}.docs-table code{color:#285582;font-size:12px;word-break:break-word}.guide-section ol{list-style:decimal;padding-left:24px}.guide-section li{padding:5px 0 5px 4px;overflow-wrap:anywhere}.docs-main a{color:#1c60a5;text-decoration:underline;text-underline-offset:3px}.docs-note{font-size:12px;color:#5f7086}.docs-notice{border-left:3px solid #c8932b;background:#fff8e9;padding:12px 16px;color:#735322}.docs-loading{padding:70px;text-align:center;color:#60748c}.no-results{font-size:12px;color:#63758a;padding:14px 5px}.download-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(205px,1fr));gap:12px;margin:24px 0}.download-grid a{display:grid;grid-template-columns:22px minmax(0,1fr);align-items:center;gap:3px 10px;padding:15px;border:1px solid #d7e0ec;border-radius:8px;color:#26578b;text-decoration:none}.download-grid a:hover{background:#f3f7fc}.download-grid small{grid-column:2;color:#6a7b90;font-size:11px}.model-search{width:100%;padding:10px 14px;border:1px solid #cad5e3;border-radius:7px;margin:0 0 20px}.model-card{margin:10px 0;border:1px solid #dce2ea;border-radius:8px;padding:0 16px}.model-card summary{cursor:pointer;padding:12px 0;font-size:13px}.model-card summary span{float:right;color:#64778d;font-size:12px}.docs-footer{border-top:1px solid #e0e6ee;margin-top:46px;padding-top:18px;display:flex;gap:15px;justify-content:space-between;flex-wrap:wrap;color:#667a92;font-size:11px}.docs-footer button{color:#245d95}.developer-docs button:focus-visible,.developer-docs a:focus-visible,.developer-docs summary:focus-visible{outline:2px solid #4087d5;outline-offset:3px}
@media(max-width:1050px){.docs-layout{grid-template-columns:240px minmax(0,1fr)}.docs-main{padding:25px}.docs-header{padding:0 20px}.docs-brand{font-size:15px}.doc-btn{font-size:11px}.environment{gap:10px 16px}}
@media(max-width:720px){.docs-header{height:auto;min-height:76px;padding:12px 16px;flex-wrap:wrap;gap:10px}.docs-brand{font-size:14px}.brand-icon{width:34px;height:34px}.docs-brand small{font-size:10px}.header-actions{gap:7px}.doc-btn{padding:5px 7px}.docs-layout{display:block}.docs-nav{position:relative;top:0;height:auto;max-height:310px;border-right:0;border-bottom:1px solid #dce2ea;padding:14px 16px}.guide-nav{grid-template-columns:repeat(2,minmax(0,1fr));padding:10px 0;gap:1px}.api-nav{font-size:12px}.docs-main{padding:24px 16px}.docs-main h1{font-size:22px}.environment{margin-bottom:25px}.docs-loading{padding:40px 20px}.endpoint-path{gap:8px;padding:10px}.transport{margin-left:0}}
@media(pointer:coarse),(max-width:640px){.doc-btn,.guide-nav a,.api-nav,.api-group summary{min-height:44px}.docs-search input,.model-search{min-height:32px;font-size:16px}.header-actions{flex-wrap:wrap}.docs-header{position:relative}.docs-main{padding:20px 16px}}
</style>
